create table refresh_tokens (expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null unique, token varchar(255) not null unique, primary key (id));
create table users (email_verified boolean not null, is_active boolean not null, id bigint generated by default as identity, email varchar(255) not null unique, password varchar(255) not null, role varchar(255) not null check ((role in ('USER','ADMIN'))), username varchar(255) not null unique, primary key (id));
create table verification_codes (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null unique, code varchar(255) not null, primary key (id));
alter table if exists refresh_tokens add constraint fk_refresh_tokens_user_id foreign key (user_id) references users;
alter table if exists verification_codes add constraint fk_verification_codes_user_id foreign key (user_id) references users on delete cascade;
